data.styles:
/* GLOBAL */
html { scroll-behavior: smooth; }
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Segoe UI', system-ui, -apple-system, sans-serif; color: var(--color-text); line-height: 1.6; background: var(--color-bg); overflow-wrap: break-word; }
h1, h2, h3 { font-weight: 800; line-height: 1.2; color: var(--color-text); }
a { color: var(--color-primary); }
ul { list-style: none; }

/* THE BAR AT THE TOP: the name, and the light/dark button when the site has one */
.site-nav { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 0.5rem 1.5rem; max-width: 64rem; margin: 0 auto; padding: 1rem 2rem 0; }
.nav-logo { font-weight: 800; color: var(--color-text); text-decoration: none; }

/* THE PAGE. On a computer, two columns: who I am at the left, my links at the right. One column on a tablet and a phone,
   in the order a phone reads: the photo and the name, the links, what is new, then a few words about me */
.page { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr); grid-template-rows: auto 1fr; gap: 1.5rem 2.5rem; align-items: start; max-width: 64rem; margin: 0 auto; padding: 1.5rem 2rem 4rem; }
.profile { grid-column: 1; grid-row: 1; }
.main-col { grid-column: 2; grid-row: 1 / span 2; }
.about { grid-column: 1; grid-row: 2; }

/* WHO I AM: a cover, a round photo over its lower edge, the name and one line */
.profile { background: var(--color-surface); border: 1px solid var(--color-border); border-radius: 1.25rem; overflow: hidden; text-align: center; padding-bottom: 1.75rem; }
.portrait { width: 8.5rem; margin: -4.25rem auto 0; position: relative; }
.profile h1 { font-size: clamp(1.8rem, 2.5vw + 1.2rem, 2.4rem); margin: 0.75rem 1.25rem 0.25rem; }
.bio { color: var(--color-text-muted); font-size: 1.1rem; margin: 0 1.25rem; }

/* PHOTOS: the template's own, each an image an author swaps for theirs; a little dimmer in the dark theme */
.photo { display: block; width: 100%; height: auto; object-fit: cover; filter: brightness(var(--photo-brightness)); }
.cover .photo { aspect-ratio: 2 / 1; }
.portrait .photo { aspect-ratio: 1 / 1; border-radius: 50%; border: 4px solid var(--color-surface); }
.card .photo { aspect-ratio: 4 / 3; }

/* MY LINKS: large buttons, one under the other, the first filled */
.links { display: flex; flex-direction: column; gap: 0.75rem; }
.pill { display: flex; align-items: center; justify-content: space-between; gap: 1rem; min-height: 3.5rem; padding: 0.75rem 1.5rem; border-radius: 999px; background: var(--color-surface); border: 2px solid var(--color-border); color: var(--color-text); font-weight: 700; font-size: 1.05rem; text-decoration: none; transition: border-color 0.2s, background 0.2s; }
.pill::after { content: '\203A'; font-size: 1.4rem; line-height: 1; color: var(--color-primary); }
.pill:hover { border-color: var(--color-primary); }
.pill-main { background: var(--color-primary); border-color: var(--color-primary); color: var(--color-on-primary); }
.pill-main::after { color: var(--color-on-primary); }
.pill-main:hover { background: var(--color-primary-strong); border-color: var(--color-primary-strong); }

/* LATELY: a card per piece of news, the first with a photo */
.lately { margin-top: 2.5rem; }
.lately h2, .about h2 { font-size: 1.1rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--color-accent); margin-bottom: 0.9rem; }
.card-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(14rem, 100%), 1fr)); gap: 1rem; }
.card { background: var(--color-surface); border: 1px solid var(--color-border); border-radius: 1.25rem; overflow: hidden; display: flex; flex-direction: column; }
.card-body { padding: 1.1rem 1.25rem 1.25rem; display: flex; flex-direction: column; flex: 1; }
.card h3 { font-size: 1.1rem; margin-bottom: 0.3rem; }
.card-desc { color: var(--color-text-muted); margin-bottom: 0.75rem; }
.more { margin-top: auto; font-weight: 700; }

/* ABOUT */
.about { padding: 0 0.25rem; }
.about p { margin-bottom: 0.75rem; }
.about-mail { display: flex; flex-wrap: wrap; gap: 0 0.4rem; color: var(--color-text-muted); }
.about-mail a { font-weight: 700; }

/* FOOTER */
.site-footer { background: var(--color-footer-bg); color: var(--color-footer-text); padding: 2.5rem 2rem 1.25rem; }
.footer-content { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start; gap: 1.5rem 2rem; max-width: 64rem; margin: 0 auto; }
.footer-logo { font-size: 1.2rem; font-weight: 800; }
.footer-brand p { color: var(--color-footer-muted); font-size: 0.9rem; margin-top: 0.35rem; }
.footer-note { max-width: 64rem; margin: 1.75rem auto 0; padding-top: 1.25rem; border-top: 1px solid rgba(255, 255, 255, 0.12); color: var(--color-footer-muted); font-size: 0.85rem; }

/* LANGUAGE SWITCH (a site in several languages) */
.footer-lang { display: flex; flex-wrap: wrap; align-items: center; gap: 0.5rem 0.75rem; }
.lang-label { color: var(--color-footer-muted); font-size: 0.9rem; }
.lang-switch { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.lang-btn { color: var(--color-footer-text); text-decoration: none; padding: 0.35rem 0.9rem; border-radius: 999px; font-size: 0.85rem; border: 1px solid rgba(255, 255, 255, 0.25); }
.lang-btn:hover { border-color: var(--color-footer-text); }

/* THEME SWITCH (a site with a dark theme) */
.theme-switch { display: inline-flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.9rem; border-radius: 999px; border: 1px solid var(--color-switch-border); background: transparent; color: var(--color-switch-text); font: inherit; font-size: 0.85rem; font-weight: 500; cursor: pointer; transition: border-color 0.2s, color 0.2s; }
.theme-switch:hover { border-color: var(--color-primary); color: var(--color-text); }

/* LESS MOTION, for a visitor who asked their system for it */
@media (prefers-reduced-motion: reduce) {
    html { scroll-behavior: auto; }
    * { transition: none !important; }
}

/* TABLET (a screen up to 64rem): one column, as on a phone, kept narrow and centred */
@media (max-width: 64rem) {
    .site-nav { max-width: 34rem; }
    .page { grid-template-columns: minmax(0, 1fr); grid-template-rows: none; max-width: 34rem; }
    .profile, .main-col, .about { grid-column: 1; grid-row: auto; }
}

/* PHONE (a screen up to 40rem): the page to the edges of the screen */
@media (max-width: 40rem) {
    .site-nav { padding: 0.75rem 1rem 0; }
    .page { padding: 1rem 1rem 2.5rem; gap: 1.25rem; }
    .lately { margin-top: 1.75rem; }
    .site-footer { padding: 2rem 1rem 1rem; }
}
